})
.AddCookie()
.AddSaml2(options =>
{
    options.SPOptions.EntityId = new EntityId("https://app.example.com");

    options.SPOptions.ReturnUrl = new Uri("https://app.example.com/");

    var identityProvider = new IdentityProvider(
        new EntityId("https://idp.example.com"), 
        options.SPOptions)
    {
        LoadMetadata = true,
        MetadataLocation = "https://idp.example.com/metadata"
    };

    options.IdentityProviders.Add(identityProvider);

    options.SPOptions.ServiceCertificates.Add(
        new X509Certificate2("signing-cert.pfx", "password"));
});

// General Programming Example
class Example {
  constructor(config) {
    this.config = {
      enabled: true,
      debug: false,
      maxRetries: 3,
      timeout: 5000,
      ...config
    };
  }

  async process(input) {
    // Step 1: Validate input
    this.validate(input);

    // Step 2: Process with retry logic
    let attempts = 0;
    while (attempts < this.config.maxRetries) {
      try {
        const result = await this.execute(input);
        return { success: true, data: result };
      } catch (error) {
        attempts++;
        if (attempts >= this.config.maxRetries) {
          return { success: false, error: error.message };
        }
      }
    }
  }

  validate(input) {
    if (!input) {
      throw new Error('Input cannot be null or undefined');
    }
  }

  async execute(input) {
    // Implementation here
    return { processed: true, timestamp: Date.now() };
  }
}

// Usage
const example = new Example({ debug: true });
example.process({ id: 1 }).then(console.log);

